/*
 * Radius presets, switched at runtime with data-radius on <html> (no attribute = default).
 * Generated from the theme-radius-<name> registry items; import after the theme.
 */

html[data-radius="none"] {
  --radius: 0rem;
}

html[data-radius="sm"] {
  --radius: 0.375rem;
}

html[data-radius="default"] {
  --radius: 0.5rem;
}

html[data-radius="lg"] {
  --radius: 0.625rem;
}

html[data-radius="xl"] {
  --radius: 0.875rem;
}
